1	package stowage
2	
3	import "sync"
4	
5	// compartment 是舱位的内部记录。
6	type compartment struct {
7		id        string
8		maxWeight int64
9		cargo     map[string]*cargo
10	}
11	
12	// cargo 是货物的内部记录。
13	type cargo struct {
14		id            string
15		weight        int64
16		destination   string
17		allowMixed    bool
18		compartmentID string // 空字符串表示未装载
19	}
20	
21	// Registry 是舱单与配载的本地登记处。
22	//
23	// Registry 的所有方法都可以安全地并发调用。
24	type Registry struct {
25		mu           sync.Mutex
26		compartments map[string]*compartment
27		cargos       map[string]*cargo
28		adjustments  map[string]*AdjustmentResult // 已成功调整的编号 -> 保存的结果快照
29		contents     map[string]string            // 已成功调整的编号 -> 规范化内容键
30	}
31	
32	// NewRegistry 创建一个空的登记处。
33	func NewRegistry() *Registry {
34		return &Registry{
35			compartments: make(map[string]*compartment),
36			cargos:       make(map[string]*cargo),
37			adjustments:  make(map[string]*AdjustmentResult),
38			contents:     make(map[string]string),
39		}
40	}
41	
42	// RegisterCompartment 登记一个舱位。
43	// 编号去掉首尾空白后不得为空，maxWeight 必须为正整数（千克）。
44	// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
45	func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
46		r.mu.Lock()
47		defer r.mu.Unlock()
48	
49		cid := trimID(id)
50		if cid == "" {
51			return fail(ErrInvalidID, "", "舱位编号为空")
52		}
53		if maxWeight <= 0 {
54			return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数千克，当前为 %d", cid, maxWeight)
55		}
56		if _, exists := r.compartments[cid]; exists {
57			return fail(ErrAlreadyExists, cid, "舱位 %s 已存在", cid)
58		}
59		r.compartments[cid] = &compartment{
60			id:        cid,
61			maxWeight: maxWeight,
62			cargo:     make(map[string]*cargo),
63		}
64		return nil
65	}
66	
67	// RegisterCargo 登记一件货物。
68	// 编号与目的地去掉首尾空白后不得为空，weight 必须为正整数（千克）。
69	// 货物登记后处于未装载状态。
70	// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
71	func (r *Registry) RegisterCargo(id string, weight int64, destination string, allowMixed bool) error {
72		r.mu.Lock()
73		defer r.mu.Unlock()
74	
75		cid := trimID(id)
76		if cid == "" {
77			return fail(ErrInvalidID, "", "货物编号为空")
78		}
79		if weight <= 0 {
80			return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
81		}
82		dest := trimID(destination)
83		if dest == "" {
84			return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
85		}
86		if _, exists := r.cargos[cid]; exists {
87			return fail(ErrAlreadyExists, cid, "货物 %s 已存在", cid)
88		}
89		r.cargos[cid] = &cargo{
90			id:          cid,
91			weight:      weight,
92			destination: dest,
93			allowMixed:  allowMixed,
94		}
95		return nil
96	}
97	
98	// Compartment 查询舱位的承重、已用重量、剩余重量与货物清单。
99	// 编号去掉首尾空白后识别；不存在时返回错误。
100	func (r *Registry) Compartment(id string) (*CompartmentView, error) {
101		r.mu.Lock()
102		defer r.mu.Unlock()
103	
104		cid := trimID(id)
105		if cid == "" {
106			return nil, fail(ErrInvalidID, "", "舱位编号为空")
107		}
108		comp, ok := r.compartments[cid]
109		if !ok {
110			return nil, fail(ErrNotFound, cid, "舱位 %s 不存在", cid)
111		}
112		view := compartmentView(comp)
113		return &view, nil
114	}
115	
116	// Cargo 查询货物的当前舱位或未装载状态。
117	// 编号去掉首尾空白后识别；不存在时返回错误。
118	func (r *Registry) Cargo(id string) (*CargoView, error) {
119		r.mu.Lock()
120		defer r.mu.Unlock()
121	
122		cid := trimID(id)
123		if cid == "" {
124			return nil, fail(ErrInvalidID, "", "货物编号为空")
125		}
126		c, ok := r.cargos[cid]
127		if !ok {
128			return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
129		}
130		return cargoView(c), nil
131	}
132	
133	// cloneResult 复制一份调整结果，避免调用方修改影响已保存的快照。
134	func cloneResult(r *AdjustmentResult) *AdjustmentResult {
135		return &AdjustmentResult{
136			ID:                 r.ID,
137			CargoChanges:       append([]CargoChange(nil), r.CargoChanges...),
138			CompartmentChanges: append([]CompartmentChange(nil), r.CompartmentChanges...),
139		}
140	}
141

