198				res, err := r.Adjust("A1", tc.ops)
199				if err == nil {
200					t.Fatalf("留有不允许混装的 G2 时应拒绝整次调整，却返回成功: %+v", res)
201				}
202				if res != nil {
203					t.Fatalf("被拒绝的调整不应返回成功结果: %+v", res)
204				}
205				se := requireError(t, err, ErrMixedLoading)
206				// 结构化原因指出 G2 并携带此次调整编号。
207				if se.ID != "G2" {
208					t.Fatalf("混装冲突应指出不允许混装的 G2，实际 ID=%q", se.ID)
209				}
210				if se.AdjustmentID != "A1" {
211					t.Fatalf("混装冲突应携带调整编号 A1，实际 AdjustmentID=%q", se.AdjustmentID)
212				}
213				// 说明中能看出涉及 C1。
214				if !strings.Contains(se.Error(), "C1") {
215					t.Fatalf("混装说明应指出舱位 C1: %s", se.Error())
216				}
217				// 拒绝后整次调整不生效：G1、G2 仍在 C1，G3 仍未装载。
218				g1, _ := r.Cargo("G1")
219				g2, _ := r.Cargo("G2")
220				g3, _ := r.Cargo("G3")
221				if g1.CompartmentID != "C1" || !g1.Loaded {
222					t.Fatalf("G1 不应被单独卸下: %+v", g1)
223				}
224				if g2.CompartmentID != "C1" || !g2.Loaded {
225					t.Fatalf("G2 应留在 C1: %+v", g2)
226				}
227				if g3.Loaded || g3.CompartmentID != "" {
228					t.Fatalf("G3 应仍未装载: %+v", g3)
229				}
230				// 已用 50、剩余 50。
231				cpt, _ := r.Compartment("C1")
232				if cpt.UsedWeight != 50 || cpt.RemainingWeight != 50 {
233					t.Fatalf("拒绝后舱位重量应保持 50/50: %+v", cpt)
234				}
235				if len(cpt.Cargo) != 2 || cpt.Cargo[0].ID != "G1" || cpt.Cargo[1].ID != "G2" {
236					t.Fatalf("C1 清单应仍是 G1、G2: %+v", cpt.Cargo)
237				}
238				assertReplaceProfilesUnchanged(t, r, true)
239			})
240		}
241	}
